<template><div class="attendance-pwa"><PwaPageHeader icon="fas fa-chart-column" title="Rekap Kehadiran" subtitle="Rekap pribadi per periode" /><div class="toolbar"><input :value="bulan" type="month" class="form-control form-control-sm" @change="$emit('update-bulan',$event.target.value)"><button class="btn btn-primary btn-sm" @click="loadData"><i class="fas fa-search"></i></button><button class="btn btn-danger btn-sm" :disabled="printing" @click="printPdf"><i class="fas fa-file-pdf"></i></button></div><div class="profile"><div class="avatar"><i class="fas fa-user"></i></div><div><strong>{{profileName}}</strong><span>{{profileNip}}</span></div></div><div class="summary"><div v-for="s in cards" :key="s.key"><span>{{s.label}}</span><strong>{{summary[s.key]||0}}</strong></div></div><div class="card"><div class="title"><div><h6>Riwayat Harian</h6><span>{{monthLabel}}</span></div></div><div v-if="loading" class="empty">Memuat rekap...</div><div v-else-if="!rows.length" class="empty">Belum ada data.</div><div v-else class="list"><div v-for="x in rows" :key="x.id" class="item"><div class="top"><strong>{{formatDate(x.tanggal)}}</strong><span class="status" :class="statusClass(x.status)">{{x.status||'-'}}</span></div><div class="times"><span>Masuk <b>{{formatTime(x.jam_masuk)}}</b></span><span>Pulang <b>{{formatTime(x.jam_pulang)}}</b></span></div><div class="location">{{locationLabel(x.lokasi_masuk)}}</div></div></div></div></div>

</template>
<script setup>import PwaPageHeader from '../../../components/PwaPageHeader.vue';defineProps({bulan:{type:String,default:''},rows:{type:Array,default:()=>[]},profile:{type:Object,default:()=>({})},loading:Boolean,printing:Boolean,summary:{type:Object,default:()=>({})},monthLabel:{type:String,default:''},profileName:{type:String,default:'-'},profileNip:{type:String,default:'-'},formatDate:{type:Function,required:true},formatTime:{type:Function,required:true},locationLabel:{type:Function,required:true},statusClass:{type:Function,required:true},loadData:{type:Function,required:true},printPdf:{type:Function,required:true}});defineEmits(['update-bulan']);const cards=[{key:'hadir',label:'Hadir'},{key:'absen',label:'Absen'},{key:'izin',label:'Izin'},{key:'cuti',label:'Cuti'},{key:'libur',label:'Libur'},{key:'lembur_jam',label:'Lembur'}]</script>
<style scoped>.attendance-pwa{padding:2px 0 84px}.toolbar{display:grid;grid-template-columns:1fr auto auto;gap:5px;padding:8px;margin-bottom:7px;background:#fff;border:1px solid #e5e7eb;border-radius:14px}.toolbar .form-control{font-size:11.88px}.toolbar .btn{font-size:10px}.profile{display:flex;align-items:center;gap:8px;padding:9px;margin-bottom:7px;background:#fff;border:1px solid #e5e7eb;border-radius:14px}.avatar{width:34px;height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:#eff6ff;color:#2563eb}.profile strong{display:block;color:#111827;font-size:13.12px}.profile span{display:block;color:#64748b;font-size:9.38px;margin-top:2px}.summary{display:grid;grid-template-columns:repeat(6,1fr);gap:5px;margin-bottom:7px}.summary>div{padding:7px 4px;border:1px solid #e5e7eb;border-radius:10px;background:#fff;text-align:center}.summary span{display:block;color:#64748b;font-size:8.75px}.summary strong{display:block;color:#111827;font-size:18.75px;margin-top:2px}.card{padding:10px;background:#fff;border:1px solid #e5e7eb;border-radius:15px}.title{margin-bottom:7px}.title h6{margin:0;color:#111827;font-size:15px}.title span{color:#64748b;font-size:10px}.list{display:flex;flex-direction:column;gap:6px}.item{padding:8px;border:1px solid #eef2f7;border-radius:11px}.top,.times{display:flex;justify-content:space-between;gap:5px}.top strong{font-size:11.25px;color:#334155}.status{padding:3px 5px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:8.75px;font-weight:900}.status.hadir,.status.approved{background:#dcfce7;color:#166534}.status.pending{background:#fef3c7;color:#92400e}.status.rejected{background:#fee2e2;color:#991b1b}.times{margin-top:6px;color:#64748b;font-size:10px}.times b{color:#334155}.location{margin-top:5px;padding-top:5px;border-top:1px solid #f1f5f9;color:#64748b;font-size:9.38px;line-height:1.3;word-break:break-word}.empty{text-align:center;padding:20px;color:#64748b;font-size:11.25px}@media(max-width:450px){.summary{grid-template-columns:repeat(3,1fr)}}@media(max-width:330px){.toolbar{grid-template-columns:1fr auto}.summary{grid-template-columns:repeat(2,1fr)}}</style>